CREATE TABLE "ProductValidation" (
 "id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"initiativeId" TEXT NOT NULL,"sprintId" TEXT NOT NULL,"storyId" TEXT NOT NULL,"demoItemId" TEXT,"sprintReviewId" TEXT,
 "validatorStakeholderId" TEXT,"validatorNameSnapshot" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'pending',"storyVersion" INTEGER NOT NULL,"storySnapshot" JSONB NOT NULL,
 "evidenceNotes" TEXT NOT NULL DEFAULT '',"evidenceLinks" JSONB NOT NULL DEFAULT '[]',"decisionReason" TEXT NOT NULL DEFAULT '',"sequence" INTEGER NOT NULL,"revision" INTEGER NOT NULL DEFAULT 1,"supersedesValidationId" TEXT,
 "createdByUserId" TEXT NOT NULL,"finalizedByUserId" TEXT,"finalizedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,
 CONSTRAINT "ProductValidation_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "ValidationCriterionResult" (
 "id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"validationId" TEXT NOT NULL,"criterionId" TEXT NOT NULL,"criterionVersion" INTEGER NOT NULL,"criterionSnapshot" JSONB NOT NULL,
 "result" TEXT NOT NULL DEFAULT 'pending',"reason" TEXT NOT NULL DEFAULT '',"evidenceNotes" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,
 CONSTRAINT "ValidationCriterionResult_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "ProductValidationRevision" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"validationId" TEXT NOT NULL,"fromRevision" INTEGER NOT NULL,"toRevision" INTEGER NOT NULL,"previousData" JSONB NOT NULL,"nextData" JSONB NOT NULL,"reason" TEXT NOT NULL,"actorUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProductValidationRevision_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ValidationFollowUp" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"validationId" TEXT NOT NULL,"planningRequestId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ValidationFollowUp_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ValidationAiSuggestion" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"validationId" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"content" TEXT NOT NULL,"informationUsed" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'proposed',"model" TEXT NOT NULL DEFAULT '',"generatedByUserId" TEXT NOT NULL,"actedByUserId" TEXT,"actedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ValidationAiSuggestion_pkey" PRIMARY KEY ("id"));

CREATE INDEX "ProductValidation_organizationId_initiativeId_status_idx" ON "ProductValidation"("organizationId","initiativeId","status");
CREATE INDEX "ProductValidation_storyId_createdAt_idx" ON "ProductValidation"("storyId","createdAt"); CREATE INDEX "ProductValidation_sprintId_status_idx" ON "ProductValidation"("sprintId","status");
CREATE UNIQUE INDEX "ProductValidation_storyId_sprintId_sequence_key" ON "ProductValidation"("storyId","sprintId","sequence");
CREATE UNIQUE INDEX "ValidationCriterionResult_validationId_criterionId_key" ON "ValidationCriterionResult"("validationId","criterionId"); CREATE INDEX "ValidationCriterionResult_organizationId_validationId_idx" ON "ValidationCriterionResult"("organizationId","validationId");
CREATE UNIQUE INDEX "ProductValidationRevision_validationId_toRevision_key" ON "ProductValidationRevision"("validationId","toRevision"); CREATE INDEX "ProductValidationRevision_organizationId_createdAt_idx" ON "ProductValidationRevision"("organizationId","createdAt");
CREATE UNIQUE INDEX "ValidationFollowUp_planningRequestId_key" ON "ValidationFollowUp"("planningRequestId"); CREATE INDEX "ValidationFollowUp_organizationId_validationId_idx" ON "ValidationFollowUp"("organizationId","validationId");
CREATE UNIQUE INDEX "ValidationAiSuggestion_validationId_fingerprint_key" ON "ValidationAiSuggestion"("validationId","fingerprint"); CREATE INDEX "ValidationAiSuggestion_organizationId_createdAt_idx" ON "ValidationAiSuggestion"("organizationId","createdAt");

ALTER TABLE "ProductValidation" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE, ADD FOREIGN KEY ("initiativeId") REFERENCES "Initiative"("id") ON DELETE CASCADE, ADD FOREIGN KEY ("sprintId") REFERENCES "Sprint"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("storyId") REFERENCES "ArtifactLayer"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("demoItemId") REFERENCES "DemoItem"("id") ON DELETE SET NULL, ADD FOREIGN KEY ("sprintReviewId") REFERENCES "SprintReview"("id") ON DELETE SET NULL, ADD FOREIGN KEY ("validatorStakeholderId") REFERENCES "StakeholderContact"("id") ON DELETE SET NULL, ADD FOREIGN KEY ("supersedesValidationId") REFERENCES "ProductValidation"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("finalizedByUserId") REFERENCES "User"("id") ON DELETE SET NULL;
ALTER TABLE "ValidationCriterionResult" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("validationId") REFERENCES "ProductValidation"("id") ON DELETE CASCADE, ADD FOREIGN KEY ("criterionId") REFERENCES "ArtifactLayer"("id") ON DELETE RESTRICT;
ALTER TABLE "ProductValidationRevision" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("validationId") REFERENCES "ProductValidation"("id") ON DELETE CASCADE, ADD FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE SET NULL;
ALTER TABLE "ValidationFollowUp" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("validationId") REFERENCES "ProductValidation"("id") ON DELETE CASCADE, ADD FOREIGN KEY ("planningRequestId") REFERENCES "PlanningRequest"("id") ON DELETE RESTRICT;
ALTER TABLE "ValidationAiSuggestion" ADD FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("validationId") REFERENCES "ProductValidation"("id") ON DELETE CASCADE, ADD FOREIGN KEY ("generatedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT, ADD FOREIGN KEY ("actedByUserId") REFERENCES "User"("id") ON DELETE SET NULL;

ALTER TABLE "ProductValidation" ADD CHECK (status IN ('pending','accepted','rejected','changes_needed')), ADD CHECK (sequence>0), ADD CHECK (revision>0), ADD CHECK (jsonb_typeof("evidenceLinks")='array'), ADD CHECK (status='pending' OR ("finalizedAt" IS NOT NULL AND "finalizedByUserId" IS NOT NULL AND char_length(btrim("decisionReason"))>=3)), ADD CHECK ("validatorStakeholderId" IS NULL OR char_length(btrim("validatorNameSnapshot"))>0);
ALTER TABLE "ValidationCriterionResult" ADD CHECK (result IN ('pending','met','not_met','not_demonstrated','not_applicable')), ADD CHECK (result<>'not_applicable' OR char_length(btrim(reason))>=3);
ALTER TABLE "ProductValidationRevision" ADD CHECK ("fromRevision">0 AND "toRevision"="fromRevision"+1), ADD CHECK (char_length(btrim(reason))>=3);
ALTER TABLE "ValidationAiSuggestion" ADD CHECK (char_length(fingerprint)=64), ADD CHECK (status IN ('proposed','used','dismissed','stale')), ADD CHECK ((status IN ('proposed','stale') AND "actedAt" IS NULL AND "actedByUserId" IS NULL) OR (status IN ('used','dismissed') AND "actedAt" IS NOT NULL AND "actedByUserId" IS NOT NULL));

CREATE FUNCTION validate_product_validation() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM "Initiative" i WHERE i.id=NEW."initiativeId" AND i."organizationId"=NEW."organizationId" AND i."projectId"=NEW."projectId") THEN RAISE EXCEPTION 'Validation tenant mismatch'; END IF;
 IF NOT EXISTS (SELECT 1 FROM "SprintPlan" sp JOIN "SprintPlanningItem" spi ON spi."sprintPlanId"=sp.id JOIN "ArtifactLayer" a ON a.id=spi."storyId" WHERE sp."initiativeId"=NEW."initiativeId" AND sp."sprintId"=NEW."sprintId" AND sp.status='committed' AND a.id=NEW."storyId" AND a.type='story') THEN RAISE EXCEPTION 'Validation requires a committed sprint story'; END IF;
 IF NEW."demoItemId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "DemoItem" d WHERE d.id=NEW."demoItemId" AND d."initiativeId"=NEW."initiativeId" AND d."sprintId"=NEW."sprintId" AND d."storyId"=NEW."storyId") THEN RAISE EXCEPTION 'Validation demo mismatch'; END IF;
 IF NEW."sprintReviewId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "SprintReview" r WHERE r.id=NEW."sprintReviewId" AND r."initiativeId"=NEW."initiativeId" AND r."sprintId"=NEW."sprintId") THEN RAISE EXCEPTION 'Validation review mismatch'; END IF;
 IF NEW."validatorStakeholderId" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "StakeholderContact" s WHERE s.id=NEW."validatorStakeholderId" AND s."organizationId"=NEW."organizationId" AND s."archivedAt" IS NULL) THEN RAISE EXCEPTION 'Validation stakeholder mismatch'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER product_validation_parent BEFORE INSERT OR UPDATE ON "ProductValidation" FOR EACH ROW EXECUTE FUNCTION validate_product_validation();
CREATE FUNCTION validate_validation_child() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_temp AS $$
DECLARE validation_org TEXT; validation_story TEXT; row_data JSONB; criterion_id TEXT;
BEGIN row_data:=to_jsonb(NEW); SELECT "organizationId","storyId" INTO validation_org,validation_story FROM "ProductValidation" WHERE id=NEW."validationId"; IF validation_org IS NULL OR validation_org<>NEW."organizationId" THEN RAISE EXCEPTION 'Validation child tenant mismatch'; END IF;
 IF TG_TABLE_NAME='ValidationCriterionResult' THEN criterion_id:=row_data->>'criterionId'; IF NOT EXISTS (SELECT 1 FROM "ArtifactLayer" a WHERE a.id=criterion_id AND a."parentId"=validation_story AND a.type='acceptance_criterion') THEN RAISE EXCEPTION 'Validation criterion mismatch'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validation_criterion_parent BEFORE INSERT OR UPDATE ON "ValidationCriterionResult" FOR EACH ROW EXECUTE FUNCTION validate_validation_child();
CREATE TRIGGER validation_followup_parent BEFORE INSERT OR UPDATE ON "ValidationFollowUp" FOR EACH ROW EXECUTE FUNCTION validate_validation_child();
CREATE TRIGGER validation_ai_parent BEFORE INSERT OR UPDATE ON "ValidationAiSuggestion" FOR EACH ROW EXECUTE FUNCTION validate_validation_child();
CREATE FUNCTION protect_final_validation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status<>'pending' THEN RAISE EXCEPTION 'Final validation is immutable; create a revalidation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER product_validation_final_immutable BEFORE UPDATE OR DELETE ON "ProductValidation" FOR EACH ROW WHEN (OLD.status<>'pending') EXECUTE FUNCTION protect_final_validation();
CREATE FUNCTION protect_validation_criterion() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE validation_status TEXT; BEGIN SELECT status INTO validation_status FROM "ProductValidation" WHERE id=OLD."validationId"; IF validation_status<>'pending' OR NEW."criterionId" IS DISTINCT FROM OLD."criterionId" OR NEW."criterionVersion" IS DISTINCT FROM OLD."criterionVersion" OR NEW."criterionSnapshot" IS DISTINCT FROM OLD."criterionSnapshot" THEN RAISE EXCEPTION 'Validation criterion evidence is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validation_criterion_immutable BEFORE UPDATE ON "ValidationCriterionResult" FOR EACH ROW EXECUTE FUNCTION protect_validation_criterion();
CREATE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Validation history is immutable'; END $$;
CREATE TRIGGER validation_revision_immutable BEFORE UPDATE OR DELETE ON "ProductValidationRevision" FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE FUNCTION protect_validation_ai() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.id,NEW."organizationId",NEW."validationId",NEW.fingerprint,NEW.content,NEW."informationUsed",NEW.model,NEW."generatedByUserId",NEW."createdAt") IS DISTINCT FROM ROW(OLD.id,OLD."organizationId",OLD."validationId",OLD.fingerprint,OLD.content,OLD."informationUsed",OLD.model,OLD."generatedByUserId",OLD."createdAt") OR (OLD.status IN ('used','dismissed') AND NEW.status IS DISTINCT FROM OLD.status) THEN RAISE EXCEPTION 'Validation AI evidence is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validation_ai_immutable BEFORE UPDATE ON "ValidationAiSuggestion" FOR EACH ROW EXECUTE FUNCTION protect_validation_ai();

ALTER TABLE "ProductValidation" ENABLE ROW LEVEL SECURITY; ALTER TABLE "ValidationCriterionResult" ENABLE ROW LEVEL SECURITY; ALTER TABLE "ProductValidationRevision" ENABLE ROW LEVEL SECURITY; ALTER TABLE "ValidationFollowUp" ENABLE ROW LEVEL SECURITY; ALTER TABLE "ValidationAiSuggestion" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON "ProductValidation","ValidationCriterionResult","ProductValidationRevision","ValidationFollowUp","ValidationAiSuggestion" FROM anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON "ProductValidation","ValidationCriterionResult","ValidationAiSuggestion" TO app_rw; GRANT SELECT,INSERT ON "ProductValidationRevision","ValidationFollowUp" TO app_rw;
CREATE POLICY product_validation_all ON "ProductValidation" FOR ALL TO app_rw USING (is_org_member("organizationId")) WITH CHECK (is_org_member("organizationId"));
CREATE POLICY validation_criterion_all ON "ValidationCriterionResult" FOR ALL TO app_rw USING (is_org_member("organizationId")) WITH CHECK (is_org_member("organizationId"));
CREATE POLICY validation_revision_select ON "ProductValidationRevision" FOR SELECT TO app_rw USING (is_org_member("organizationId")); CREATE POLICY validation_revision_insert ON "ProductValidationRevision" FOR INSERT TO app_rw WITH CHECK (is_org_member("organizationId"));
CREATE POLICY validation_followup_select ON "ValidationFollowUp" FOR SELECT TO app_rw USING (is_org_member("organizationId")); CREATE POLICY validation_followup_insert ON "ValidationFollowUp" FOR INSERT TO app_rw WITH CHECK (is_org_member("organizationId"));
CREATE POLICY validation_ai_all ON "ValidationAiSuggestion" FOR ALL TO app_rw USING (is_org_member("organizationId")) WITH CHECK (is_org_member("organizationId"));
